(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.012-t*0.2)*12;
  const w1y = Math.cos(y*0.018-t*0.25)*18 + Math.sin(x*0.015+t*0.35)*12;
  const w2x = Math.sin(x*0.035-t*0.5)*6 + Math.cos(y*0.04+t*0.4)*4;
  const w2y = Math.cos(y*0.03+t*0.45)*6 + Math.sin(x*0.038-t*0.55)*4;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.7+3)*70, 40+Math.cos(t*0.3)*50, 0.14, 2.1, 0.85],
    [400+Math.cos(t*0.45+2)*60, 200+Math.sin(t*0.65)*40, 0.11, 1.8, 1.05]
  ];
  let aS = 0, iS = 0, hS = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    hS += Math.sin(d*f*1.3 - t*sp*0.4 + 3.0) * w;
  }
  const n = src.length, act = aS/n, inh = iS/n, harm = hS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.08+sy*0.06-t*1.5)*0.15 + Math.sin(sx*0.06-sy*0.09+t*1.8)*0.1;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.07-ang*2+t*0.8)*0.2;
  const v1x = 180+Math.sin(t*0.3)*60, v1y = 100+Math.cos(t*0.4)*40;
  const v2x = 300+Math.cos(t*0.35)*50, v2y = 140+Math.sin(t*0.45)*50;
  const d1 = Math.sqrt((sx-v1x)**2+(sy-v1y)**2), d2 = Math.sqrt((sx-v2x)**2+(sy-v2y)**2);
  const a1 = Math.atan2(sy-v1y, sx-v1x), a2 = Math.atan2(sy-v2y, sx-v2x);
  const vortex = Math.sin(d1*0.06-a1*5+t*2)*0.3 + Math.sin(d2*0.05+a2*4-t*1.8)*0.3;
  const rd = act - inh*0.65 + bg*0.25 + spiral*0.3 + vortex*0.2 + harm*0.15;
  const reaction = Math.tanh(rd * 2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)
    + Math.sin((sx+sy)*0.1+t)*0.5 + Math.sin(sx*0.22-sy*0.18+t*0.7)*0.3)*1.5)*0.25;
  const fine = Math.sin(sx*0.4+sy*0.3+t*3)*Math.sin(sx*0.35-sy*0.45-t*2.5)*0.15;
  const blend = reaction*0.65 + cell*0.2 + fine*0.15, v = blend*0.5+0.5;
  const pal = [
    [5,15,55],[10,45,85],[15,85,105],[30,135,130],[85,170,120],
    [180,185,80],[220,175,60],[235,135,65],[215,85,70],[170,50,65],
    [90,25,55],[35,15,50],[5,15,55]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge = Math.abs(reaction)>0.65?1.2:1.0;
  const glow = Math.max(0, reaction-0.3)*0.5;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*30)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*15)|0)
  ];
}
